async function testTenantDashboardScale() {
  await provisionTenant({ id: 'tenantA' });
  const wsPool = new WebSocketPool('/stream/tenantA', 1000);
  await wsPool.connectAll();
  // emit synthetic events, verify aggregates stay tenant-scoped
  await verifyIsolation('tenantA');
  await simulateRBACChangeMidSession('tenantA', 'viewer', 'editor');
  await verifyAccess('tenantA', 'editor');
  await throttleNetwork(1000);
  await verifyLatencyPercentile('tenantA', 95);
